    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def wrapper(func):
        def memoized_func(*args, **kwargs):
            if key is not None:
                key_value = key(*args, **kwargs)
            else:
                key_value = args
            if key_value in cache:
