import time

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    cache = {}
    last_accessed = {}

    def wrapper(func):
        def memoized_func(*args, **kwargs):
            key = (args, frozenset(kwargs.items()))
            if key in cache:
                if timer() - last_accessed[key] > ttl:
                    del cache[key]
                    del last_accessed[key]
                else:
                    return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            last_accessed[key] = timer()
            if len(cache) > maxsize:
                oldest_key = min(last_accessed, key=last_accessed.get)
                del cache[oldest_key]
                del last_accessed[oldest_key]
            return result
        return memoized_func
    return wrapper
```

